/* Generated by safe ES module refactor from the existing js/main.js implementation. */

import { API_BASE, REQUEST_TIMEOUT_MS, RETRYABLE_STATUS_CODES } from "./config.js";
import { clearCurrentUser, getCurrentUser, touchCurrentUserActivity } from "./auth.js";
import { ADMIN_LOGIN_PAGE, USER_LOGIN_PAGE } from "./routing.js";
import { showMessage } from "../ui/toast.js";

export function apiUrl(path) {
  const normalizedPath = String(path || "").startsWith("/") ? String(path) : `/${path}`;
  return `${API_BASE}${normalizedPath}`;
}

export async function readJsonSafely(response) {
  try {
    return await response.json();
  } catch (err) {
    return {};
  }
}

export async function readResponseBody(response) {
  const contentType = String(response.headers.get("content-type") || "").toLowerCase();
  if (contentType.includes("application/json")) return readJsonSafely(response);

  try {
    return await response.text();
  } catch (err) {
    return "";
  }
}

export function extractErrorMessage(data, fallbackMessage) {
  if (typeof data === "string" && data.trim()) return data.trim();
  if (data && typeof data.error === "string" && data.error.trim()) return data.error.trim();
  if (data && typeof data.message === "string" && data.message.trim()) return data.message.trim();
  if (data && typeof data.title === "string" && data.title.trim()) return data.title.trim();
  return fallbackMessage;
}

export function isAbortError(err) {
  return Boolean(err && (err.name === "AbortError" || /abort|timed out/i.test(String(err.message || ""))));
}

export async function fetchWithTimeout(
  url,
  options = {},
  timeoutMs = REQUEST_TIMEOUT_MS,
) {
  const controller = new AbortController();
  const timeoutId = window.setTimeout(() => controller.abort(), timeoutMs);

  try {
    return await fetch(url, {
      cache: "no-store",
      ...options,
      signal: controller.signal,
    });
  } finally {
    window.clearTimeout(timeoutId);
  }
}

export async function requestJson(path, options = {}) {
  const {
    method = "GET",
    headers = {},
    body,
    timeoutMs = REQUEST_TIMEOUT_MS,
    retries,
  } = options;

  const normalizedMethod = String(method || "GET").toUpperCase();
  const retryCount =
    retries !== undefined ? retries : normalizedMethod === "GET" ? 1 : 0;
  const mergedHeaders = { Accept: "application/json", ...headers };
  const fetchOptions = { method: normalizedMethod, headers: mergedHeaders };

  if (body !== undefined) {
    if (!mergedHeaders["Content-Type"])
      mergedHeaders["Content-Type"] = "application/json";
    fetchOptions.body =
      typeof body === "string" ? body : JSON.stringify(body);
  }

  for (let attempt = 0; attempt <= retryCount; attempt += 1) {
    const response = await fetchWithTimeout(
      apiUrl(path),
      fetchOptions,
      timeoutMs,
    );
    const data = await readResponseBody(response);

    if (
      !response.ok &&
      RETRYABLE_STATUS_CODES.has(response.status) &&
      attempt < retryCount
    ) {
      await new Promise((resolve) =>
        window.setTimeout(resolve, 400 * (attempt + 1)),
      );
      continue;
    }

    if (response.ok) touchCurrentUserActivity();
    return { ok: response.ok, status: response.status, data, path };
  }

  return { ok: false, status: 0, data: {}, path };
}

export function getAuthHeader() {
  const currentUser = getCurrentUser();
  if (currentUser && currentUser.token) {
    return { Authorization: `Bearer ${currentUser.token}` };
  }

  return {};
}

export function isAuthFailureStatus(status) {
  return status === 401 || status === 403;
}

export function handleUserAuthFailure(status) {
  if (!isAuthFailureStatus(status)) return false;
  showMessage("Session expired. Please login again.", "error");
  clearCurrentUser();
  window.setTimeout(() => window.location.replace(USER_LOGIN_PAGE), 850);
  return true;
}

export function handleAdminAuthFailure(status) {
  if (status === 401) {
    showMessage("Admin session expired. Please login again.", "error");
    clearCurrentUser();
    window.setTimeout(() => window.location.replace(ADMIN_LOGIN_PAGE), 850);
    return true;
  }

  if (status === 403) {
    showMessage("You do not have permission to access that admin resource.", "error");
    return true;
  }

  return false;
}
